DECLARE
   vNoTrans      VARCHAR2 (32767);
   vLbuId        VARCHAR2 (32767);
   vLdcId        VARCHAR2 (32767);
   vAccountNo    VARCHAR2 (32767);
   vLbgId        VARCHAR2 (32767);
   vTglAksep     DATE;
   vNett         NUMBER;
   vLkuId        VARCHAR2 (32767);
   vLjtdId       VARCHAR2 (32767);
   vNoPolis      VARCHAR2 (32767);
   vAcceptType   VARCHAR2 (32767);
   vDeductible   NUMBER;
   vKaliDeduct   NUMBER;
   vKepada     VARCHAR2 (32767);
   vEmail        VARCHAR2 (32767);
   vCaseID       VARCHAR2 (32767);
   vStsSyariah  VARCHAR2 (32767);
   vnote  VARCHAR2 (32767);
   vstsdsa VARCHAR2 (32767);

BEGIN
  vNoTrans      := {TempTransferKasir.CountryID};
  vLbuId        :={TempTransferKasir.Email};
  vLdcId        :={TempTransferKasir.CreateFrom};
  vAccountNo    :={TempTransferKasir.Currency};
  vLbgId        :={TempTransferKasir.DistrictID};
  vTglAksep     :={TempTransferKasir.UserName Datetime};
  vNett         :={TempTransferKasir.City};
  vLkuId        :={TempTransferKasir.CityID};
  vLjtdId       :={TempTransferKasir.AnaylstRemarks};
  vCaseID       :={TempTransferKasir.CaseID};
  vNoPolis      :={TempTransferKasir.AnalystDoctorRemaks};
  vAcceptType   :={TempTransferKasir.ClaimID};
  vDeductible   :={TempTransferKasir.ClaimNo};
  vKaliDeduct   :={TempTransferKasir.Country};
  vKepada     :={TempTransferKasir.Remark};
  vEmail        :={TempTransferKasir.CauseOfLoss};
  vStsSyariah :={TempTransferKasir.UserAdmin};
  vnote  := {TempTransferKasir.ResponseNote};
  vstsdsa := {TempTransferKasir.StatusReceiver};

   gl.pkg_pelunasan_kasir.p_insert_all_payment_kasir(vNoTrans,
                                                      vLbuId,
                                                      vLdcId,
                                                      vAccountNo,
                                                      vLbgId,
                                                      vTglAksep,
                                                      '0',
                                                      vNett,
                                                      vLkuId,
                                                      vLjtdId,
                                                      '',
                                                      '',
                                                      vCaseID,
                                                      vNoPolis,
                                                      vAcceptType,
                                                      vDeductible,
                                                      vKaliDeduct,
                                                      '',
                                                      '',
                                                      vKepada,
                                                      '',
                                                      vEmail,
                                                      '',
                                                      vstsdsa,
                                                      vStsSyariah,
                                                      '',
                                                      '',
                                                      {TempTransferKasir.CloseClaimNote out},
                                                      '',
                                                      '',
                                                      vnote,
                                                      '',
                                                      '');
   COMMIT;
END;
